#[test]
fn s16e_poison_injection() {
    use blubber::Resize as _;
    let mut bytes = [0; 64];
    let mut store = blubber::SliceStore::new(&mut bytes);
    FixedRemoval::initialize(&mut store, FixedRemovalInit { values: &[(1, 7), (3, 9)] }).unwrap();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut root = FixedRemoval::load_trusted_mut(&mut store).unwrap();
        root.values_mut().remove(&1).unwrap();
    }));
    assert!(result.is_err());
    assert!(store.is_poisoned());
}
"}]

